/**-------------------------- Log Multi Tenor dates Data --------------------------**/
i = 0;

while (i < tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

	tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_MultiTenorDates ( " + " requesrID, installmentDate, installmentAmount, INSTALLMENTBASEDATE, INSTALLMENTTENORDAYS, REBATEAMOUNT " + " ) VALUES" + " (?,?,?,?,?,?)";

	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.requestID));
	var instalmentMaturityDate = addOneHourToDate(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentMaturityDate);
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(instalmentMaturityDate));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount));
	var instalmentBaseDate = addOneHourToDate(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentBaseDate);
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(instalmentBaseDate));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentTenorDays));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].splitRebateAmnt));
	i++;
}

/**-------------------------- Log Delivery Terms --------------------------**/
i = 0;

while (i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

	tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_DELIVERYTERMS ( " + " REQUESTID, DELIVERYTERMVALUE" + " ) VALUES" + " (?,?)";

	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.requestID));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms[i].value));

	i++;
}
/**-------------------------- Log Delivery Terms Extra--------------------------**/
i = 0;

while (i < tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

	tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_DELIVERYTERMSEXTRA ( " + " REQUESTID, DELIVERYTERMEXTRA" + " ) VALUES" + " (?,?)";

	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.requestID));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[i]));

	i++;
}

/**-------------------------- Log Payment Instructions --------------------------**/
i = 0;

while (i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructions.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

	tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_PAYMENTINSTRUCTIONS ( " + " REQUESTID, PAYMENTINSTRUCTIONSVALUE" + " ) VALUES" + " (?,?)";

