while (i < tw.local.odcRequest.GeneratedDocumentInfo.paymentInstructionsExtra.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

	tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_PAYMENTINSTRUCTIONSEXTRA ( " + " REQUESTID, PAYMENTINSTRUCTIONSEXTRA" + " ) VALUES" + " (?,?)";

