/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}

/*********************************************************************************************************************************************/

tw.local.sql =
	"UPDATE " +
	tw.env.LKP_DB_Schema +
	".ODC_RequestInfo SET (" +
	" requestNature ,requestType  ,requestDate , requestState  , requestStatus , parentRequestNo,         		       " +
	" fcContractNo ,contractStage , exportPurpose ,paymentTerms ,productCategory, commodityDescription,  			 " +
	" cif, customerName, baseDate , valueDate, tenorDays, transitDays, contractMaturityDate, userRef, productCode,         " +
	" productDesc, stage, sourceRef, tradeFoRefNo, discount, extraCharges, ourCharges, amountSight,amountDefNoAvalization, " +
	" amountDefAvalization, collectableAmount," +
	"outstandingAmount, maturityDate, maturityDays," +
	"financeApprovalNo," +
	"hubCode,  " +
	" hubName, collectionCurrency, standardExRate, negotiatedExRate,          					  			 " +
	" CBEClassification, shipmentMethod, shipmentDate, 						 						 " +
	" importerName, importerCountry, importerAddress, importerPhoneNo, importerBank, bicCode, ibanAccount, 			 " +
	" bankCountry, bankAddress, bankPhoneNo, collectingBankRef, allocatedAmount, totalAllocatedAmount  	,ISLIQUIDATED ,	 " +
	" BPMInstanceNumber, currentStepName, substatus, 											 	" +
	"  TRANSACTIONREFNO, MAXIMUMCOLLECTIONDATE, REQUESTCURRENCY, DOCUMENTAMOUNT, ADVANCEAMOUNT, COLLECTIONACCOUNT, CHARGESACCOUNT,COUNTRYOFORIGIN,FCCONTRACTNO2,FCCONTRACTNO3,CHARGESACCOUNTCURRENCY,CHARGESACCOUNTBALANCE,COLLECTIONACCOUNTCURRENCY,COLLECTIONACCOUNTBALANCE,CUSTOMERNAMEINDOC,CUSTOMERADDRESSINDOC,FOLDERPATH ,CBEGOODSCODE , GOVERNMENTCOTTON ,INCOTERMS, OPERATIONTYPECODE, GOODDESTINATION, REBATEAMOUNT " +
	" ) " +
	" =(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?" +
	",?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?" +
	")" +
	" WHERE requestNo = ? ";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.requestNature.name));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.odcRequest.requestType.value));
