		tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

		tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_Invoice ( " + " requesrID, invoiceNo , invoiceDate" + " ) VALUES" + " (?,?,?)";

		tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.requestID));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo));

		var invoiceDate = addOneHourToDate(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate);
		if (invoiceDate) {
			//			invoiceDate.setDate(invoiceDate.getDate() + 1);
			tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(invoiceDate));
		}

		i++;
	}

	/**-------------------------- Log Bills Data --------------------------**/
	i = 0;

	while (i < tw.local.odcRequest.BasicDetails.Bills.listLength) {
		sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
		tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

		tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_Bills ( " + " requesrID, billOfLadingRef, billOfLadingDate" + " ) VALUES" + " (?,?,?)";

		tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.requestID));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef));

		var billDate = addOneHourToDate(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate);
		//		if (!!billDate) billDate.setDate(billDate.getDate() + 1);
		if (billDate) tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(billDate));

		i++;
	}
}

function resetHoursToMidnight(date) {
	var resetDate = new Date(date);
	resetDate.setHours(0, 0, 0, 0);
	return resetDate;
}

// add function to add 1hour to the input date
function addOneHourToDate(date) {
	if (date == null) return null;
	var newDate = new Date(date);
	newDate.setHours(newDate.getHours() + 1);
	return newDate;
}

