ns16:scriptTask.ns16:script:
tw.local.sqlStatements = new tw.object.listOf.toolkit.TWSYS.SQLStatement();

/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	return parameter;
}
/***********************************************************************************/

/**-----------------------------------------------------------------------**/
/**-------------------------- Log All ODC Data ---------------------------**/
/**-----------------------------------------------------------------------**/

var i = 0;
var sqlStatementLen = 0;

/**-------------------------- Log Parties Data --------------------------**/

/**-------------------------- Set SQL query to add party record --------------------------**/
function AuditParty(requesrID, partyId, partyType, cif, partyName, country, language, reference, address1, address2, address3, media, address) {
	if (!!partyId) {
		sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;

		tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

		tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_PartiesInfo ( " + " requesrID, partyId, partyType, cif, partyName,Country,Language," + "  Reference, Address1, Address2, Address3, Media, Address" + " ) VALUES" + " (?,?,?,?,?,?,?,?,?,?,?,?,?) ";
		tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(requesrID));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(partyId));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(partyType));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(cif));

		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(partyName));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(country));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(language));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(reference));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(address1));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(address2));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(address3));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(media));
		tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(address));

		return true;
	} else {
		return false;
	}
}

//Params: requesrID, partyId , partyType, cif, partyName, country, language, reference, address1, address2, address3, media, address
//Audit Drawer
AuditParty(tw.local.requestID, tw.local.odcRequest.Parties.Drawer.partyId, "Drawer", "", tw.local.odcRequest.Parties.Drawer.partyName, tw.local.odcRequest.Parties.Drawer.country, tw.local.odcRequest.Parties.Drawer.Language, tw.local.odcRequest.Parties.Drawer.Reference, tw.local.odcRequest.Parties.Drawer.address1, tw.local.odcRequest.Parties.Drawer.address2, tw.local.odcRequest.Parties.Drawer.address3, "", "");

//Audit Drawee
AuditParty(tw.local.requestID, tw.local.odcRequest.Parties.Drawee.partyId, "Drawee", "", tw.local.odcRequest.Parties.Drawee.partyName, tw.local.odcRequest.Parties.Drawee.country, tw.local.odcRequest.Parties.Drawee.Language, tw.local.odcRequest.Parties.Drawee.Reference, tw.local.odcRequest.Parties.Drawee.address1, tw.local.odcRequest.Parties.Drawee.address2, tw.local.odcRequest.Parties.Drawee.address3, "", "");

//Audit collecting Bank
AuditParty(
	tw.local.requestID,
	tw.local.odcRequest.Parties.collectingBank.id,
	"collecting Bank",
	tw.local.odcRequest.Parties.collectingBank.cif,
	tw.local.odcRequest.Parties.collectingBank.name,
	tw.local.odcRequest.Parties.collectingBank.country,
	tw.local.odcRequest.Parties.collectingBank.language,
	tw.local.odcRequest.Parties.collectingBank.reference,
	tw.local.odcRequest.Parties.collectingBank.address1,
	tw.local.odcRequest.Parties.collectingBank.address2,
	tw.local.odcRequest.Parties.collectingBank.address3,
	tw.local.odcRequest.Parties.collectingBank.media,
	tw.local.odcRequest.Parties.collectingBank.address
);

//Audit Accountee/ Case In Need
if (tw.local.odcRequest.Parties.caseInNeed && !!tw.local.odcRequest.Parties.caseInNeed.partyId) {
	AuditParty(
		tw.local.requestID,
		tw.local.odcRequest.Parties.caseInNeed.partyId,
		"CASE IN NEED",
		tw.local.odcRequest.Parties.caseInNeed.partyCIF,
		tw.local.odcRequest.Parties.caseInNeed.partyName,
		tw.local.odcRequest.Parties.caseInNeed.country,
		tw.local.odcRequest.Parties.caseInNeed.language,
		tw.local.odcRequest.Parties.caseInNeed.refrence,
		tw.local.odcRequest.Parties.caseInNeed.address1,
		tw.local.odcRequest.Parties.caseInNeed.address2,
		tw.local.odcRequest.Parties.caseInNeed.address3,
		"",
		""
	);
}

/**-------------------------- Log Charges And Commissions Data --------------------------**/

i = 0;

while (i < tw.local.odcRequest.ChargesAndCommissions.listLength) {
	sqlStatementLen = tw.local.sqlStatements.listLength ? tw.local.sqlStatements.listLength : 0;
	tw.local.sqlStatements[sqlStatementLen] = new tw.object.toolkit.TWSYS.SQLStatement();

	tw.local.sqlStatements[sqlStatementLen].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_CHARGESCOMMISSIONS ( " + " requesrID, defaultCurrency, defaultAmount, chargeAmount, waiver, accountClass," + " accountNo, branchCode, currency, balance, balanceSign, standardExRate," + "negotiatedExRate, debitedAmount, COMPONENT" + " ) VALUES" + " (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";

	tw.local.sqlStatements[sqlStatementLen].parameters = new tw.object.listOf.toolkit.TWSYS.SQLParameter();

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.requestID));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.ChargesAndCommissions[i].defaultCurrency.value));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.ChargesAndCommissions[i].defaultAmount));
	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount));

	if (tw.local.odcRequest.ChargesAndCommissions[i].waiver) tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter("1"));
	else tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter("0"));

	if (!tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount) tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount = {};

	if (!tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass) tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass = {};

	tw.local.sqlStatements[sqlStatementLen].parameters.insertIntoList(tw.local.sqlStatements[sqlStatementLen].parameters.listLength, addSQLParameter(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass.value));

